const fs=require('node:fs'),path=require('node:path');
const root=path.resolve('../3. 产品功能截图_20260921');
const sets=['1.0','2.0'].map(v=>JSON.parse(fs.readFileSync(path.join(root,'manifest-'+v+'.json'),'utf8')));
if(sets.some(s=>s.errors.length||s.failures.length))throw Error('Capture errors remain; inspect manifests before packaging.');
const rows=sets.flatMap(s=>s.records),E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Remove only obsolete PNGs generated by earlier passes of this capture task.
for(const v of ['1.0','2.0']){const dir=path.join(root,v+'产品'),keep=new Set(rows.filter(r=>r.version===v).map(r=>path.basename(r.file)));for(const name of fs.readdirSync(dir))if(name.endsWith('.png')&&!keep.has(name))fs.unlinkSync(path.join(dir,name));}
const intro='1.0 为 GIS + SCADA 基础功能；2.0 截图聚焦新增模型与计算能力，产品本身同时包含 1.0 功能。水力优先使用随州真实计算结果，水质、水龄及多时刻场景采用杭州标准演示数据。';
let md='# 产品 1.0 / 2.0 功能截图\n\n整理日期：2026-09-21 · 截图尺寸：1600 × 1000 · 原型当前版本\n\n'+intro+'\n\n打开 [截图浏览目录](截图浏览目录.html)，可按版本、模块筛选，搜索页面，点击图片查看大图。\n\n工单与巡检样例通过真实页面表单创建，截图来自独立浏览器；未改动日常浏览器中的业务记录。历史记录为空时保留实际空态；AI 智能体为规划入口，本套不将其计为已实现功能。浅色为主，附暗色主题示例。\n';
for(const version of ['1.0','2.0']){const group=rows.filter(r=>r.version===version);md+='\n## 产品 '+version+' · '+group.length+' 张\n\n| 序号 | 模块 | 功能截图 | 项目 / 数据 |\n|---|---|---|---|\n';group.forEach((r,i)=>{md+=`| ${i+1} | ${r.module} | [${r.title}](<${r.file}>) | ${r.project} · ${r.source}${r.note?'；'+r.note:''} |\n`;});}
fs.writeFileSync(path.join(root,'功能截图目录.md'),md);
fs.writeFileSync(path.join(root,'截图清单.json'),JSON.stringify({date:'2026-09-21',resolution:'1600x1000',total:rows.length,records:rows},null,2));
const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>城市供水管网 · 产品功能截图</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#142a43;font:14px/1.6 "Microsoft YaHei",system-ui,sans-serif}header{padding:36px 5vw 26px;background:#071f35;color:#fff}header small{color:#8cbbef;letter-spacing:2px}h1{font-size:30px;margin:8px 0 12px}header p{max-width:1000px;color:#c1d0df;margin:0}.stats{display:flex;gap:28px;margin-top:20px}.stats strong{font-size:22px;color:#fff}.stats span{color:#acc3db;margin-left:7px}nav{position:sticky;top:0;z-index:5;background:#fffffff2;border-bottom:1px solid #dce5ef;padding:16px 5vw;display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,select,input{font:inherit;border:1px solid #cfdae6;border-radius:7px;padding:8px 13px;background:white;color:#234364}button{cursor:pointer}button.active{background:#1677ff;color:white;border-color:#1677ff}input{min-width:250px}nav span{margin-left:auto;color:#637d94}main{padding:25px 5vw 50px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{background:white;border:1px solid #dfe7ef;border-radius:10px;overflow:hidden;box-shadow:0 4px 18px #17365806}.preview{display:block;border:0;border-radius:0;padding:0;width:100%;background:#e8edf4;overflow:hidden;aspect-ratio:1.6;position:relative}.preview img{display:block;width:100%;height:100%;object-fit:contain;transition:transform .16s}.preview:hover img{transform:scale(1.025)}.body{padding:15px 18px 18px}.tags{font-size:11px;color:#2466aa;display:flex;gap:8px}.tags span{background:#edf5ff;border-radius:4px;padding:2px 7px}h2{font-size:16px;margin:9px 0 7px}.meta{color:#687f94;font-size:12px}.note{font-size:12px;color:#8c6417;margin-top:7px}.empty{padding:80px;text-align:center;color:#6b8297}footer{padding:24px 5vw;border-top:1px solid #dce5ef;color:#647e93;font-size:12px}dialog{max-width:96vw;width:1520px;max-height:96vh;padding:0;border:0;border-radius:10px;box-shadow:0 15px 90px #0006}dialog::backdrop{background:#041321d9}.bar{display:flex;gap:10px;align-items:center;padding:12px 18px;position:sticky;top:0;background:white;z-index:2}.bar strong{flex:1}.bar a{color:#1677ff;text-decoration:none}#large{display:block;width:100%;height:auto}#caption{margin:0;padding:12px 18px;background:#f0f5fa;color:#546b80;font-size:12px}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid{grid-template-columns:1fr}h1{font-size:24px}nav{position:static}nav span{margin-left:0}}@media print{nav,dialog,footer{display:none}header{color:black;background:white}header p{color:#444}.grid{display:block}.card{break-inside:avoid;margin-bottom:24px;box-shadow:none}}
</style><header><small>WATER NETWORK · PRODUCT GALLERY</small><h1>城市供水管网 · 功能截图</h1><p>${E(intro)}</p><div class="stats"><div><strong>${sets[0].records.length}</strong><span>1.0 基础功能截图</span></div><div><strong>${sets[1].records.length}</strong><span>2.0 新增功能截图</span></div><div><strong>1600 × 1000</strong><span>PNG 原图</span></div></div></header>
<nav><button data-v="all" class="active">全部</button><button data-v="1.0">产品 1.0</button><button data-v="2.0">产品 2.0</button><select id="module" aria-label="按模块筛选"><option value="">全部模块</option></select><input id="search" type="search" placeholder="搜索功能、项目或数据来源" aria-label="搜索截图"><span id="count"></span></nav><main><div id="grid" class="grid"></div></main><footer>2026-09-21 · 当前产品原型实屏截图 · 点击图片放大，方向键切换，Esc 关闭。AI 智能体为规划入口，未列入已实现功能截图。工单与巡检样例来自独立截图环境；历史空态按现有页面保留。</footer>
<dialog id="viewer"><div class="bar"><button id="previous" aria-label="上一张">←</button><button id="next" aria-label="下一张">→</button><strong id="title"></strong><a id="original" target="_blank">查看原图</a><button id="close">关闭 ×</button></div><img id="large" alt=""><p id="caption"></p></dialog><script>
const records=${JSON.stringify(rows).replace(/</g,'\u003c')};const grid=document.getElementById('grid'),moduleSelect=document.getElementById('module'),search=document.getElementById('search'),viewer=document.getElementById('viewer');let version='all',visible=[],position=0;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function modules(){const selected=moduleSelect.value;moduleSelect.innerHTML='<option value="">全部模块</option>'+[...new Set(records.filter(r=>version==='all'||r.version===version).map(r=>r.module))].map(m=>'<option>'+esc(m)+'</option>').join('');if([...moduleSelect.options].some(o=>o.value===selected))moduleSelect.value=selected;}
function render(){const q=search.value.trim().toLowerCase();visible=records.filter(r=>(version==='all'||r.version===version)&&(!moduleSelect.value||r.module===moduleSelect.value)&&[r.title,r.module,r.project,r.source,r.note].join(' ').toLowerCase().includes(q));document.getElementById('count').textContent='显示 '+visible.length+' / '+records.length+' 张';grid.innerHTML=visible.map((r,i)=>'<article class="card"><button class="preview" data-i="'+i+'" aria-label="放大 '+esc(r.title)+'"><img loading="lazy" src="'+encodeURI(r.file)+'" alt="'+esc(r.title)+'"></button><div class="body"><div class="tags"><span>'+r.version+'</span><span>'+esc(r.module)+'</span></div><h2>'+String(i+1).padStart(2,'0')+' · '+esc(r.title)+'</h2><div class="meta">'+esc(r.project)+'<br>'+esc(r.source)+'</div>'+(r.note?'<div class="note">'+esc(r.note)+'</div>':'')+'</div></article>').join('')||'<p class="empty">没有符合条件的截图</p>';}
function show(i){position=(i+visible.length)%visible.length;const r=visible[position];document.getElementById('large').src=encodeURI(r.file);document.getElementById('large').alt=r.title;document.getElementById('title').textContent=(position+1)+' / '+visible.length+' · '+r.title;document.getElementById('original').href=encodeURI(r.file);document.getElementById('caption').textContent=r.project+' · '+r.source+(r.note?' · '+r.note:'');if(!viewer.open)viewer.showModal();viewer.scrollTop=0;}
document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{version=b.dataset.v;document.querySelectorAll('[data-v]').forEach(x=>x.classList.toggle('active',x===b));modules();render();});search.oninput=render;moduleSelect.onchange=render;grid.onclick=e=>{const b=e.target.closest('[data-i]');if(b)show(+b.dataset.i);};document.getElementById('close').onclick=()=>viewer.close();document.getElementById('previous').onclick=()=>show(position-1);document.getElementById('next').onclick=()=>show(position+1);document.addEventListener('keydown',e=>{if(viewer.open&&e.key==='ArrowRight')show(position+1);if(viewer.open&&e.key==='ArrowLeft')show(position-1);});modules();render();
</script></html>`;
fs.writeFileSync(path.join(root,'截图浏览目录.html'),html);
console.log(JSON.stringify({root,total:rows.length,versions:sets.map(s=>s.records.length)}));
